mapper.select:
select
    b.record,
    b.role,
    b.addition_info
from t_model_history a
         left join t_history_record b on a.id = b.history_id and b.is_deleted = 0
where a.is_deleted = 0
  and a.groups_id = #{groupId}
  and a.user_id = #{userId}
  and a.elemen_id = #{elementId}
  and a.model_name in

        #{modelName}

order by b.create_date,b.id

select a.groups_id, a.model_name, count(b.role) roundCount, sum(b.word_number) questionWords from t_model_history a left join t_history_record b on a.id = b.history_id and b.is_deleted = 0 where a.is_deleted = 0 and a.groups_id = #{groupId} and a.model_name in
#{modelName}
and b.role = #{user} group by a.model_name

select sum(b.record_time) spentTime,
       sum(b.word_number) answerWords
from t_model_history a
         left join t_history_record b on a.id = b.history_id and b.is_deleted = 0
where a.is_deleted = 0
  and a.groups_id = #{groupsId}
  and a.model_name = #{modelName}
  and b.role = #{role}

select count(a.user_id)
from t_model_history a
where a.is_deleted = 0
  and a.groups_id = #{groupsId}
  and a.model_name =#{modelName}

select model_name modelUser, model_id modelId, count(distinct user_id) number from t_model_history where is_deleted = 0 and groups_id = #{groupId} and elemen_id = #{elementId} and model_id in
#{modelId}
group by model_name,model_id

select
    a.user_id userId,
    a.model_name modelName,
    a.model_id modelId,
    count(*) number
from t_model_history a
left join t_history_record b on a.id = b.history_id and b.role = 'assistant' and b.is_deleted = 0
where a.is_deleted = 0
and a.elemen_id = #{elementId}
and a.groups_id = #{groupId}
and a.model_id in

    #{modelId}

group by a.user_id,a.model_name, a.model_id;

select a.user_id modelUser, ROUND(avg(word_number)) number from t_model_history a left join t_history_record b on a.id = b.history_id and b.role = 'user' and b.is_deleted = 0 where a.is_deleted = 0 and a.elemen_id = #{elementId} and a.groups_id = #{groupId} and a.model_id in
#{modeId}
group by a.user_id

select a.model_name modelUser, a.model_id modelId, ROUND(avg(word_number)) number from t_model_history a left join t_history_record b on a.id = b.history_id and b.role = 'assistant' and b.is_deleted = 0 where a.is_deleted = 0 and a.elemen_id = #{elementId} and a.groups_id = #{groupId} and a.model_id in
#{modelId}
group by a.model_name,a.model_id

select a.model_name modelUser, a.model_id modelId, ROUND(avg(b.record_time)) number from t_model_history a left join t_history_record b on a.id = b.history_id and b.is_deleted = 0 and b.role ='user' where a.is_deleted = 0 and a.elemen_id = #{elementId} and a.groups_id = #{groupId} and a.model_id in
#{modelId}
group by a.model_name,a.model_id
